with remaining_keys as (select page from web_events except select page from web_events where duration_sec >= 329), verified as (select s.* from web_events s inner join remaining_keys k on s.page = k.page) select s.session_id, s.event_type, s.page, s.duration_sec, (select avg(x.duration_sec) from web_events x where x.session_id = s.session_id) as avg_web_event_duration_sec from verified s order by avg_web_event_duration_sec desc, duration_sec desc
